const input = $input.first().json;

// Get the incoming data from the n8n Webhook
let data = input.body ?? input;

// If the request arrives as text/plain, parse its JSON string
if (typeof data === 'string') {
  try {
    data = JSON.parse(data);
  } catch (error) {
    throw new Error('INVALID_JSON: Could not parse submitted form data');
  }
}

// Read both new website fields and old n8n Form Trigger fields
const name = String(data.fullName ?? data['Full Name'] ?? '').trim();

const email = String(data.email ?? data['Email Address'] ?? '')
  .trim()
  .toLowerCase();

const phone = String(data.phone ?? data['Phone Number'] ?? '').trim();

const consentValue =
  data.consent ?? data['I agree to be contacted'];

const consent =
  consentValue === true ||
  ['true', 'yes', 'on', '1'].includes(
    String(consentValue).trim().toLowerCase()
  );

// Validate email
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

// Validate phone, allowing normal US formatting
const phoneDigits = phone.replace(/\D/g, '');

const phoneValid =
  /^[+\d\s().-]+$/.test(phone) &&
  phoneDigits.length >= 7 &&
  phoneDigits.length <= 15;

// Required field validation
if (!name || !email || !phone) {
  throw new Error('MISSING_FIELDS: Name, email or phone is empty');
}

if (!emailValid) {
  throw new Error('INVALID_EMAIL: ' + email);
}

if (!phoneValid) {
  throw new Error('INVALID_PHONE: ' + phone);
}

if (!consent) {
  throw new Error('NO_CONSENT: Lead did not agree to be contacted');
}

// Normalize data while preserving compatibility with existing nodes
return [{
  json: {
    ...input,
    ...data,

    // Original field names for existing workflow nodes
    'Full Name': name,
    'Email Address': email,
    'Phone Number': phone,
    'I agree to be contacted': consent,

    // Website form information
    intent: data.intent ?? '',
    preferredArea: data.preferredArea ?? '',
    budgetRange: data.budgetRange ?? '',
    additionalNotes: data.additionalNotes ?? '',

    validatedAt: new Date().toISOString()
  }
}];

